ק. הַצַּדִּיק יְסוֹד עוֹלָם הוּא בְּחִינַת הַתִּקּוּן שֶׁל כָּל הָעוֹלָמוֹת, שֶׁזֶּה בְּחִינַת אוֹר מַה הֶחָדָשׁ וְכֵן מֶלֶךְ הַשְּׁמִינִי שֶׁהוּא הָדָר (שֶׁהוּא בְּחִינַת יְסוֹד בְּחִינַת הַצַּדִּיק שֶׁהַמַּקִּיפִים שֶׁלּוֹ הֵם בְּחִינַת מַה בְּחִינַת מָה רַב טוּבְךָ שֶׁזֶּה בְּחִינַת אוֹר מַה הֶחָדָשׁ). שֶׁעַל יְדֵי זֶה עוֹלָם הַתִּקּוּן כַּמְּבֹאָר בְּכִתְבֵי הָאֲרִ"י זַ"ל, כִּי כָּל הַשְּׁבִירָה הָיָה עַל יְדֵי רִבּוּי אוֹר מֵחֲמַת שֶׁלֹּא יָכְלוּ הַכֵּלִים לִסְבֹּל הָאוֹר הָרַב וְעַל יְדֵי זֶה נִשְׁבְּרוּ וְנָפְלוּ וְהָאוֹר עָלָה לְמַעְלָה. וְאַחַר כָּךְ נִתַּקְּנוּ. רַק כַּמָּה נִיצוֹצוֹת נִשְׁאֲרוּ עֲדַיִן לְמַטָּה שֶׁבָּזֶה עוֹסְקִין כָּל יִשְׂרָאֵל וְהַצַּדִּיקִים שֶׁבְּכָל דּוֹר לְהַעֲלוֹתָם. וְהַנִּיצוֹצוֹת נָפְלוּ וְנִתְפַּשְּׁטוּ בְּכָל הָעוֹלָמוֹת אֲפִלּוּ בְּתַכְלִית הָעֲשִׂיָּה, עַד שֶׁנִּתְפַּשְּׁטוּ אֲפִלּוּ בַּבְּהֵמוֹת וְחַיּוֹת וְעוֹפוֹת וּבְכָל דָּבָר. וְכָל הַתִּקּוּן הוּא עַל יְדֵי הַצַּדִּיק הָאֱמֶת הַגָּדוֹל בְּמַעֲלָה מְאֹד, כִּי הוּא יָכוֹל לְהָאִיר בְּדָרֵי מַעְלָה וּלְהַרְאוֹת לָהֶם שֶׁהֵם רְחוֹקִים עֲדַיִן מֵהַשֵּׁם יִתְבָּרַךְ וְאֵינָם יוֹדְעִים כְּלָל בִּידִיעָתוֹ יִתְבָּרַךְ, וְעַל יְדֵי זֶה הוּא מְחַיֶּה וּמְתַקֵּן אוֹתָם שֶׁלֹּא יַזִּיק לָהֶם רִבּוּי הָאוֹר, שֶׁעַל יְדֵי זֶה הָיְתָה הַשְּׁבִירָה כַּנַּ"ל. וְכֵן הוּא מֵאִיר לְהַדָּרֵי מַטָּה שֶׁיֵּדְעוּ כִּי מְלֹא כָּל הָאָרֶץ כְּבוֹדוֹ וַה' עִמָּם וְאֶצְלָם. וְעַל יְדֵי זֶה הוּא מְחַיֶּה וּמְתַקֵּן כָּל הַנִּיצוֹצוֹת הַנְּפוּלִין הַנַּ"ל שֶׁמֵּחֲמַת גֹּדֶל יְרִידָתָן שָׁכְחוּ אֶת מַעֲלָתָן וְנִדְמֶה לָהֶם שֶׁהֵם רְחוֹקִים מְאֹד מִמֶּנּוּ יִתְבָּרַךְ עַד שֶׁאֵינָם יְכוֹלִים עוֹד לְהָרִים עַצְמָם לַעֲלוֹת לְמַעְלָה, וְהַצַּדִּיק מְחַיֶּה אוֹתָם עַל יְדֵי בְּחִינַת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ בִּבְחִינַת תְּחִיַּת הַמֵּתִים, שֶׁהוּא בְּחִינַת עוֹלָם הַתִּקּוּן, בְּחִינַת יִחְיוּ מֵתֶיךָ וְכוּ' הָקִיצוּ וְרַנְּנוּ שׁוֹכְנֵי עָפָר. נִמְצָא שֶׁעַל יְדֵי הַצַּדִּיק הַגָּדוֹל הַנַּ"ל נִתְתַּקְּנִין כָּל הָעוֹלָמוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים עַד תַּכְלִית מַדְרֵגָה הָאַחֲרוֹנָה הַנַּ"ל (הלכות סימני בהמה וחיה הלכה ב). 
קא. הַצַּדִּיקִים מִתְיַגְּעִים כָּל יְמֵי חַיֵּיהֶם לְגַלּוֹת הָאֱמוּנָה הַקְּדוֹשָׁה בָּעוֹלָם, וּלְהוֹדִיעַ גַּם לְהָרְחוֹקִים מְאֹד אֲשֶׁר הַטוֹב שֶׁיֵּשׁ בָּהֶם מִקְּדֻשַּׁת יִשְׂרָאֵל כְּבָר כָּבוּשׁ וְנֶעֱלָם אֶצְלָם מְאֹד, אַף עַל פִּי כֵן יִזְכְּרוּ גַּם הֵם אֶת מַעֲלַת קְדֻשָּׁתָם מִשֹּׁרֶשׁ נִשְׁמָתָם עַד שֶׁיַּחְזְרוּ וְיָשׁוּבוּ אֶל ה'. אַךְ מֵחֲמַת שֶׁצְּרִיכִין לָזֶה אֲוִיר נֹחַ וְזַךְ בִּכְדֵי שֶׁיִּהְיוּ נִשְׁמָעִין הֵיטֵב לְכָל אֶחָד אֶת דִּבְרֵי הַצַּדִּיקִים, כִּי בְּאִם אֵין הָאֲוִיר נֹחַ וְזַךְ אֲזַי הָרוּחַ סְעָרָה מְבַלְבֵּל עַד שֶׁאֵין שׁוֹמְעִין כְּלָל אֶת הַדִּבּוּרִים הַקְּדוֹשִׁים שֶׁלָּהֶם, וַאֲוִיר נֹחַ וְזַךְ נַעֲשָׂה עַל יְדֵי הָאַהֲבָה וְהַשָּׁלוֹם שֶׁיֵּשׁ בֵּין יִשְׂרָאֵל. וְעַל כֵּן מִתְגָּרֶה עַצְמוֹ הַבַּעַל דָּבָר בְּכָל דּוֹר וּמַרְבֶּה מַחֲלֹקֶת בְּיִשְׂרָאֵל, עַד שֶׁיֵּשׁ הַרְבֵּה שֶׁחוֹלְקִין גַּם עַל הַצַּדִּיק בְּעַצְמוֹ, וְעַל יְדֵי זֶה נִתְבַּלְבֵּל אֲוִיר הָעוֹלָם וְאֵין נִשְׁמָעִין דִּבְרֵי הַצַּדִּיקִים הַנַּ"ל. אַךְ אַף עַל פִּי כֵן וְאַתָּה מָרוֹם לְעוֹלָם ה', כִּי הַצַּדִּיקִים מִשְׁתַּדְּלִים וּמִתְיַגְּעִים בְּעִנְיַן זֶה כָּל כָּךְ לְטוֹבַת יִשְׂרָאֵל וְאֵינָם מִסְתַּלְּקִים מִן הָעוֹלָם עַד שֶׁזּוֹכִין בְּיוֹם הִסְתַּלְּקוּתָם לְקַדֵּשׁ אֶת אֲוִיר הָעוֹלָם בִּקְדֻשָּׁה נִפְלָאָה כָּזֹאת, עַד שֶׁלֹּא יִהְיֶה כֹּחַ לְשׁוּם מַחֲלֹקֶת וּלְשׁוּם רוּחַ סְעָרָה לְבַלְבֵּל הָאֲוִיר, רַק דִּבּוּרֵיהֶם יֵלְכוּ וְיִתְפַּשְּׁטוּ בָּעוֹלָם וְיִהְיוּ נִשְׁמָעִים לְמֶרְחַקִּים בִּבְחִינַת יָפוּצוּ מַעַיְנוֹתֶיךָ חוּצָה, עַד שֶׁכָּל הָעוֹלָם יַחְזְרוּ וְיָשׁוּבוּ עַל יְדֵי זֶה לְהַשֵּׁם יִתְבָּרַךְ. וְאַף עַל פִּי שֶׁנִּדְמֶה שֶׁהָרוּחַ סְעָרָה גָּדוֹל בִּשְׁעָתוֹ וּכְבָר יֵשׁ יוֹתֵר מִמֵּאָה שָׁנָה אַחַר הִסְתַּלְּקוּת הַבַּעַל שֵׁם טוֹב זַצַ"ל. וְאַף עַל פִּי כֵן יֵשׁ עֲדַיִן הַרְבֵּה שֶׁחוֹלְקִין עָלָיו בְּעַצְמוֹ מִכָּל שֶׁכֵּן עַל אֲנָשָׁיו וְתַלְמִידָיו הַקְּדוֹשִׁים וְכֵן הוּא בְּכָל דּוֹר. אַף עַל פִּי כֵן סוֹף כָּל סוֹף יִתְגַּלֶּה הָאֱמֶת וּשְׂפַת אֱמֶת תִּכּוֹן לָעַד. וְגַם עַכְשָׁו בְּעֶזְרַת הַשֵּׁם כְּבָר יֵשׁ הַרְבֵּה הַמַּכִּירִין הָאֱמֶת וּמְחַבְּבִים דִּבְרֵי הַצַּדִּיקִים בְּלִי שִׁעוּר, וְרוֹאִים וּמְבִינִים מְעַט עֹצֶם נִפְלְאוֹת קְדֻשַּׁת תּוֹרָתָם וְהַשָּׂגָתָם הַקְּדוֹשָׁה וְהַגְּבוֹהָה מְאֹד. כִּי גְּדוֹלִים צַדִּיקִים בְּמִיתָתָם יוֹתֵר מִבְּחַיֵּיהֶם. וְדַיְקָא עַל יְדֵי שֶׁנִּסְתַּלֵּק וְיוֹצְאִין נַפְשׁוֹ וְרוּחוֹ וְנִשְׁמָתוֹ הַקְּדוֹשִׁים מְאֹד לַחֲזֹר לִמְקוֹרָם, וְנִשְׁאָר הֶאָרָה גְּדוֹלָה מֵהַשְׁאָרַת נַפְשׁוֹ בְּזֶה הָעוֹלָם עַל קִבְרוֹ הַקָּדוֹשׁ כַּמְּבֹאָר בְּכִתְבֵי הָאֲרִ"י זַ"ל, עַל יְדֵי זֶה נִתְקַדֵּשׁ כָּל אֲוִיר הָעוֹלָם בִּקְדֻשָּׁה גְּדוֹלָה בְּאֹפֶן שֶׁיִּהְיוּ נִשְׁמָעִין דְּבָרָיו הַקְּדוֹשִׁים לְמֶרְחַקִּים מְאֹד תָּמִיד, וְזֶה מַעֲלַת קְדֻשַּׁת קִבְרֵי הַצַּדִּיקִים כִּי שָׁם הָאֲוִיר קָדוֹשׁ מְאֹד בְּחִינַת אֲוִיר הַנֹּחַ וְהַזַּךְ בְּיוֹתֵר. וְעַל יְדֵי זֶה זוֹכִין לִשְׁמֹעַ קוֹל דִּבְרֵי הַצַּדִּיק הָאֱמֶת שֶׁכָּל דִּבּוּרָיו הָיוּ כָּל יְמֵי חַיָּיו לְהַמְשִׁיךְ אֱמוּנָה הַקְּדוֹשָׁה בָּעוֹלָם. וְעַל יְדֵי זֶה נִתְעוֹרֵר הַטוֹב שֶׁכָּבוּשׁ אֵצֶל כָּל אֶחָד וְחוֹזֵר לְמַעֲלָתוֹ. וְעַל כֵּן טוֹב לִלְמֹד עַל קִבְרֵי צַדִּיקִים מִחִדּוּשֵׁי תּוֹרָתָם, כִּי שָׁם מֵחֲמַת שֶׁהָאֲוִיר נֹחַ וְזַךְ יָכוֹל כָּל אֶחָד לִזְכּוֹת שֶׁיִּהְיוּ נִשְׁמָעִין בְּלִבּוֹ הֵיטֵב דִּבְרֵי הַצַּדִּיקֵי אֱמֶת עַד שֶׁיָּשׁוּב לְהַשֵּׁם יִתְבָּרַךְ. וְעַל כֵּן מַרְבִּין בִּצְדָקָה עַל קִבְרֵי הַצַּדִּיקִים, כִּי צְדָקָה מְסֻגָּל לָזֶה לְהַמְשִׁיךְ אֲוִיר נֹחַ וְזַךְ, וְעַל יְדֵי זֶה זוֹכִין בְּיוֹתֵר לְהִכָּלֵל בְּהָאֲוִיר הַקָּדוֹשׁ הַנֹּחַ וְהַזַּךְ שֶׁיֵּשׁ בִּמְקוֹם קִבְרֵי הַצַּדִּיקֵי אֱמֶת כַּנַּ"ל (שם הלכה ד

). 
קג. כְּלָלִיּוּת כָּל הַצַּדִּיקִים שֶׁבְּכָל דּוֹר שֶׁהֵם בְּחִינַת שִׁבְעַת הַנֵּרוֹת כֻּלָּם צְרִיכִים לְהִשְׁתַּדֵּל לְהָאִיר אֶל מוּל פְּנֵי הַמְּנוֹרָה הַיְנוּ לְהַמְשִׁיךְ אוֹר הַצַּדִּיק הָאֱמֶת בָּעוֹלָם, שֶׁהַצַּדִּיק הַזֶּה הוּא יָחִיד בְּדוֹרוֹ וְהוּא בְּחִינַת נְקֻדַּת הָאֱמֶת שֶׁבֵּין הַצַּדִּיקִים וְהוּא יָכוֹל לְתַקֵּן הַכֹּל. כִּי יֵשׁ כַּמָּה צַדִּיקִים אֲמִתִּיִּים וְכֻלָּם אֱמֶת. אֲבָל זֶה הָאֱמֶת שֶׁלָּהֶם אֵינוֹ יָכוֹל עֲדַיִן לְהַכְנִיעַ וּלְבַטֵּל לְגַמְרֵי אֶת הַשֶּׁקֶר. כִּי הַשֶּׁקֶר מִתְגַּבֵּר בְּכָל פַּעַם בִּשְׁקָרִים וְרַמָּאוּת כָּאֵלּוּ עַד שֶׁמְּקַלְקֵל זֶה הַתִּקּוּן וְהָאֱמֶת שֶׁהִמְשִׁיכוּ אֵלּוּ הַצַּדִּיקִים בָּעוֹלָם. וְלִפְעָמִים מִתְגַּבֵּר אַחַר כָּךְ הַסִּטְרָא אָחֳרָא וְהַשֶּׁקֶר דַּיְקָא עַל יְדֵי זֶה הָאֱמֶת יוֹתֵר וְיוֹתֵר, כִּי יוֹנֵק מִזֶּה הָאֱמֶת וּמְהַפְּכוֹ לִשְׁקָרָיו וְרַמָּאוּתָיו עַד שֶׁדַּיְקָא עַל יְדֵי זֶה הָאֱמֶת הַשֶּׁקֶר מִתְגַּבֵּר בְּיוֹתֵר, וְכַנִּרְאֶה בְּחוּשׁ כַּמָּה פְּעָמִים עִנְיָן זֶה. וְזֶה כְּעֵין שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל חֲכָמִים הִזָּהֲרוּ בְּדִבְרֵיכֶם וְכוּ' וּכְמוֹ שֶׁפֵּרֵשׁ שָׁם הָרַב בַּרְטְנוּרָא. וְכֵן רוֹאִין גַּם עַכְשָׁו כַּמָּה פְּעָמִים. אֲבָל זֶה הַצַּדִּיק הַגָּדוֹל בְּמַעֲלָה מְאֹד שֶׁהוּא בְּחִינַת נְקֻדַּת הָאֱמֶת שֶׁבֵּין הַצַּדִּיקִים בְּעַצְמָן, הוּא יוֹדֵעַ לְהַמְשִׁיךְ אֱמֶת כָּזֶה בָּעוֹלָם שֶׁאִי אֶפְשָׁר לְקַלְקְלוֹ בְּשׁוּם אֹפֶן. וְאַף עַל פִּי שֶׁכְּנֶגְדּוֹ מִתְגַּבֵּר הַשֶּׁקֶר בְּיוֹתֵר וּבוֹדִין עָלָיו שְׁקָרִים וּכְזָבִים וַעֲלִילוֹת שֶׁלֹּא עָלוּ עַל דַּעְתּוֹ, וְזֶה נוֹהֵג כִּמְעַט בְּכָל דּוֹר, וְהָרִאשׁוֹן הָיָה אַבְרָהָם אָבִינוּ שֶׁאָמְרוּ עָלָיו בִּשְׁבִיל הַמִּין הַזֶּה הָיָה רָעָב. וְכֵן אָמְרוּ רַבּוֹתֵינוּ זַ"ל שֶׁחֲשָׁדוּהוּ לְמשֶׁה בְּאֵשֶׁת אִישׁ, וְכֵן יִרְמִיָּהוּ הַנָּבִיא וְכֵן עוֹד עַל כַּמָּה וְכַמָּה גְּדוֹלֵי הַצַּדִּיקִים יְחִידֵי הַדּוֹרוֹת אָמְרוּ עֲלֵיהֶם דַּיְקָא שְׁקָרִים וּכְזָבִים כָּאֵלֶּה. אֲבָל אַף עַל פִּי כֵן סוֹף כָּל סוֹף דִּבְרֵיהֶם חַיִּים וְקַיָּמִים לָעַד וְלָנֶצַח, וְדִבְרֵי הַחוֹלְקִין בְּטֵלִין וּמְבֻטָּלִין כִּי שְׂפַת אֱמֶת תִּכּוֹן לָעַד. וְעַל כֵּן כָּל הַצַּדִּיקִים וְהַכְּשֵׁרִים אֲמִתִּיִּים צָרִיךְ שֶׁיִּהְיֶה כָּל עֲבוֹדָתָם לְהַמְשִׁיךְ אוֹר זֶה הַצַּדִּיק בָּעוֹלָם, כִּי עַל יָדוֹ נִמְשָׁךְ וְנִתְגַּלָּה שֹׁרֶשׁ תַּכְלִית נְקֻדַּת הָאֱמֶת עַד שֶׁנִּתְבַּטֵּל הַשֶּׁקֶר לְגַמְרֵי עַד קָצֶה הָאַחֲרוֹן (שם ל). 
קד. כָּל סִפּוּרֵי הַתּוֹרָה מִמַּעֲשֵׂה הָאָבוֹת מֵחֲפִירוֹת הַבְּאֵרוֹת וּמֵהַמַּקְלוֹת אֲשֶׁר פִּצֵּל בָּרְהָטִים וְכֵן כָּל כַּיּוֹצֵא בָּזֶה וְכֵן כָּל הַמַּאֲמָרִים הַפְּלִיאִים שֶׁהֵבִיאוּ בַּגְּמָרָא וּמִדְרָשִׁים כְּמוֹ מַאֲמְרֵי רַבָּה בַּר בַּר חָנָא וְכַיּוֹצֵא, כָּל זֶה לְהוֹדִיעַ לָנוּ מַעֲלַת הַצַּדִּיקִים שֶׁזִּכְּכוּ אֶת עַצְמָם כָּל כָּךְ עַד שֶׁעָבְדוּ אֶת הַשֵּׁם יִתְבָּרַךְ בְּכָל תְּנוּעוֹתֵיהֶם אֲפִלּוּ בְּכָל עִסְקֵי חֹל אֲכִילָה וּשְׁתִיָּה וְכַיוֹצֵא, וְכָל דִּבְרֵיהֶם וְשִׂיחוֹתֵיהֶם וּמַעֲשֵׂיהֶם אֵינוֹ פָּשׁוּט אֶלָּא יֵשׁ בָּהֶם רָזִין נִפְלָאִים. וּבֶאֱמֶת בְּכָל דּוֹר נִמְצָאִים צַדִּיקִים כָּאֵלּוּ כַּמּוּבָן בְּדִבְרֵי רַבּוֹתֵינוּ זַ"ל שֶׁאָמְרוּ שֶׁאֵין דּוֹר שֶׁאֵין בּוֹ כְּאַבְרָהָם וְכוּ', וְכָל אֶחָד צָרִיךְ לִזְכּוֹת לָזֶה בִּבְחִינַת מָתַי יַגִּיעוּ מַעֲשַׂי לְמַעֲשֵׂי אֲבוֹתַי כִּי הַבְּחִירָה חָפְשִׁית (סימני דגים הלכה ד

). 
קה. הַצַּדִּיקֵי אֱמֶת הַנַּ"ל שֶׁזָּכוּ לַעֲבֹד אֶת הַשֵּׁם יִתְבָּרַךְ בְּכָל דְּבָרִים גַּשְׁמִיִּים וְעִסְקֵי חֹל שֶׁבָּעוֹלָם, וְזָכוּ לַהֲפֹךְ הַכֹּל מִחֹל לְקֹדֶשׁ, עַל כֵּן יֵשׁ לָהֶם כֹּחַ לְהַעֲלוֹת כָּל נַפְשׁוֹת יִשְׂרָאֵל הַחוֹסִים בְּצִלָּם מִחֹל לְקֹדֶשׁ וּמִטָּמֵא לְטָהוֹר, וְלַהֲפֹךְ הַכֹּל לְטוֹבָה בְּכֹחַ הַגְּדֻלּוֹת וְהַנִּפְלָאוֹת שֶׁהִשִּׂיגוּ עַל יְדֵי תֹּקֶף קְדֻשָּׁתָם בְּכָל עִסְקֵי חֹל (שם). 
קו. הַמֹּחִין שֶׁל הַצַּדִּיק קְדוֹשִׁים וּמְתֻקָּנִים כָּל כָּךְ עַד אֲשֶׁר אֲפִלּוּ כְּשֶׁנִּסְתַּלְּקִין הַמֹּחִין וְלֹא נִשְׁאָר מֵהֶם רַק הָרְשִׁימוּ הָרְשִׁימָה גַּם כֵּן קְדוֹשָׁה מְאֹד בִּבְחִינַת חֲלוֹם עַל יְדֵי מַלְאָךְ. וְעַל כֵּן אֲפִלּוּ כְּשֶׁנִּסְתַּלֵּק הַצַּדִּיק בְּעַצְמוֹ גַּם כֵּן חַס וְשָׁלוֹם, אֲזַי הָרְשִׁימָה שֶׁלּוֹ שֶׁנִּשְׁאַר בְּתַלְמִידָיו קְדוֹשָׁה גַּם כֵּן מְאֹד בִּבְחִינַת מַלְאָךְ, שֶׁזֶּה בְּחִינַת מַה שֶּׁאַחַר הִסְתַּלְּקוּת משֶׁה בָּא מַלְאַךְ ה' אֶל יְהוֹשֻׁעַ וְאָמַר לוֹ עַתָּה בָּאתִי וְכוּ' (שם הלכה ה

). 
קיח. עִנְיַן הַצַּדִּיק שֶׁיֵּשׁ לוֹ כֹּחַ לַעֲשׂוֹת פְּתָחִים דִּקְדֻשָּׁה מֵרוּם כָּל דַּרְגִּין עַד סוֹף כָּל דַּרְגִּין, עַד שֶׁעַל יְדֵי זֶה יָכוֹל לְהַמְשִׁיךְ הֶאָרַת אֱלֹקוּתוֹ יִתְבָּרַךְ גַּם לְמַטָּה מַטָּה מְאֹד, עַיֵּן חַיִּים וְכוּ' אוֹת כד. 
קיט. עִקַּר נֶחָמָתֵינוּ בַּגָּלוּת הַמַּר וְהָאָרֹךְ הַזֶּה הִיא הַתּוֹרָה הַקְּדוֹשָׁה, כְּמוֹ שֶׁכָּתוּב: זֹאת נֶחָמָתִי בְּעָנְיִי וְכוּ'. אֲבָל לָאו כָּל אָדָם זוֹכֶה לְקַבֵּל עֵצוֹת טוֹבוֹת מֵהַתּוֹרָה הַקְּדוֹשָׁה כָּרָאוּי לוֹ בְּכָל עֵת, מֵחֲמַת שֶׁאֵין כְּלֵי הַמֹּחִין שֶׁלּוֹ שְׁלֵמִים עַל יְדֵי פְּגַם הַבְּרִית, וְעַל כֵּן יוּכַל לְהִצְטַיֵּר אֶצְלוֹ אוֹר הַתּוֹרָה לְהֵפֶךְ חַס וְשָׁלוֹם בִּבְחִינַת לֹא זָכָה נַעֲשֵׂית לוֹ סַם מָוֶת רַחֲמָנָא לִצְּלָן. עַל כֵּן הַכֹּל צְרִיכִין לְהַצַּדִּיק הָאֱמֶת הַמְבָאֵר וּמְצַיֵּר לָנוּ אוֹר הַתּוֹרָה לְטוֹב. וְזֶה עִקַּר תִּקְוָתֵנוּ וְנֶחָמָתֵינוּ בְּכָל מִינֵי גָּלוּת בְּגַשְׁמִיּוּת וְרוּחָנִיּוּת בַּכְּלָל וּבַפְּרָט, בִּבְחִינַת זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂינוּ וְכוּ' זֶה הוּא בְּחִינַת הַצַּדִּיק הָאֱמֶת שֶׁנִּקְרָא זֶה, כְּמוֹ שֶׁכָּתוּב: כִּי זֶה כָּל הָאָדָם. וּכְמַאֲמַר רַבּוֹתֵינוּ זַ"ל, כָּל הָעוֹלָם לֹא נִבְרָא אֶלָּא לְצַוּוֹת לָזֶה וְכוּ', וְזֶה עִקַּר נֶחָמָתֵינוּ. וְעַל יְדֵי הַצַּדִּיקֵי הָאֱמֶת הָאֵלּוּ הַמְצַיְּרִים אֶת הָאוֹר לְטוֹב עַל יְדֵי זֶה נַעֲשִׂין בְּכָל מָקוֹם דְּרָכִים יְשָׁרִים לְהַשֵּׁם יִתְבָּרַךְ אֲפִלּוּ בְּמָקוֹם שֶׁהָיָה מִדְבַּר שְׁמָמָה. וְכָל הַדְּרָכִים הַמְּקֻלְקָלִים וְהַנְּבוֹכִים מְאֹד שֶׁנִּמְשְׁכוּ עַל יְדֵי שֶׁלֹּא זָכִינוּ לְצַיֵּר אוֹר הַתּוֹרָה כָּרָאוּי נִתְיַשְּׁרִים וְנִתְתַּקְּנִים כָּל הַדְּרָכִים הַנַּ"ל מִקִּלְקוּלָם עַל יְדֵי הַצַּדִּיקֵי אֱמֶת שֶׁהֵם בְּחִינַת הִתְנוֹצְצוּת מָשִׁיחַ, שֶׁאָז יִתְקַיֵּם וְנָתַתִּי לָהֶם לֵב אֶחָד וְדֶרֶךְ אֶחָד לְיִרְאָה אוֹתִי כָּל הַיָּמִים בִּמְהֵרָה בְּיָמֵינוּ אָמֵן (הלכות יין נסך הלכה ד

). 
קכ. עִקַּר כָּל הַתִּקּוּנִים תְּלוּיִים בְּזֶה הָעוֹלָם הָעֲשִׂיָּה הַגַּשְׁמִי, שֶׁעַל יְדֵי שֶׁהָאָדָם הַבַּעַל בְּחִירָה מְדַבֵּק אֶת עַצְמוֹ בְּהַשֵּׁם יִתְבָּרַךְ מִזֶּה הָעוֹלָם הַגַּשְׁמִי שֶׁהוּא בְּחִינַת תַּכְלִית נְקֻדָּה הַתַּחְתּוֹנָה שֶׁל כְּלָלִיּוּת הַבְּרִיאָה, כִּי עוֹלָם הָעֲשִׂיָּה הוּא בְּחִינַת רַגְלִין בְּחִינַת וְהָאָרֶץ הֲדוֹם רַגְלָי עַל יְדֵי זֶה דַּיְקָא נִכְלָל כָּל הָעוֹלָם הַזֶּה עִם כָּל הָעוֹלָמוֹת הַתְּלוּיִים בּוֹ לְמַעְלָה לְמַעְלָה עַד שֶׁיֻּכְלַל הַכֹּל בִּבְחִינַת קֹדֶם הַבְּרִיאָה. וְכָל זֶה זוֹכִין עַל יְדֵי אֱמוּנַת הַהַשְׁגָּחָה, שֶׁמַּאֲמִינִים שֶׁהַשֵּׁם יִתְבָּרַךְ בְּעֹצֶם נִפְלְאוֹת רוֹמְמוּתוֹ יִתְבָּרַךְ הוּא צוֹפֶה וּמַבִּיט בְּהַשְׁגָּחָה פְּרָטִיּוּת עַד סוֹף תַּכְלִית דְּיוֹטָא הַתַּחְתּוֹנָה שֶׁל זֶה הָעוֹלָם הָעֲשִׂיָּה, וְעַל יְדֵי זֶה נִכְלָל אַחַר הַבְּרִיאָה בְּקֹדֶם הַבְּרִיאָה. וְעַל כֵּן אַשְׁרֵיהֶם שֶׁל הַהוֹלְכִים בְּרַגְלֵיהֶם לִדְבַר מִצְוָה. מִכָּל שֶׁכֵּן כְּשֶׁנּוֹסֵעַ וְהוֹלֵךְ לְצַדִּיקֵי אֱמֶת וְהַנִּלְוִים אֲלֵיהֶם. כִּי הַצַּדִּיק הָאֱמֶת כְּבָר זָכָה עַל יְדֵי אֲמִתַּת עֲבוֹדָתוֹ הַקְּדוֹשָׁה לְהִכָּלֵל הַכֹּל בְּקֹדֶם הַבְּרִיאָה. וּמִי שֶׁזּוֹכֶה לִנְסֹעַ וְלֵילֵךְ אֵלָיו וְהַהֲלִיכָה הִיא בְּרַגְלִין, עַל יְדֵי זֶה הוּא מַגְבִּיהַּ בְּחִינַת רַגְלִין בְּחִינַת כְּלַל עוֹלָם הָעֲשִׂיָּה שֶׁהִיא בְּחִינַת רַגְלִין מַגְבִּיהַּ הַכֹּל לְהַשֵּׁם יִתְבָּרַךְ וְכוֹלֵל אַחַר הַבְּרִיאָה בְּקֹדֶם הַבְּרִיאָה שֶׁזֶּה עִקַּר כָּל הַתִּקּוּנִים. וְעַל כֵּן צְרִיכִין הָעִקָּר לִנְסֹעַ וְלֵילֵךְ עַל רֹאשׁ הַשָּׁנָה, כִּי אָז צְרִיכִין לַעֲסֹק בָּזֶה בְּיוֹתֵר מֵחֲמַת שֶׁאָז נִבְרָא הָעוֹלָם וּצְרִיכִין לַחֲזֹר וְלִכְלֹל הָעוֹלָם בְּקֹדֶם הַבְּרִיאָה, שֶׁזֶּה עִקַּר הַתְּשׁוּבָה שֶׁל רֹאשׁ הַשָּׁנָה כַּמְּבֹאָר בִּפְנִים. וְעַל כֵּן הָיוּ נוֹהֲגִין בְּכָל הַדּוֹרוֹת לֵילֵךְ לְהָרַב. כִּי מַעֲלָה יְתֵרָה כְּשֶׁהוֹלְכִין אֵלָיו כִּי עַל יְדֵי הַהֲלִיכָה בְּעַצְמָהּ מְתַקֵּן הַרְבֵּה. וְהַהֲלִיכָה אֶל הַצַּדִּיק הוּא בְּחִינַת הַהֲלִיכָה שֶׁהָלְכוּ כָּל יִשְׂרָאֵל אֶל בֵּית הַמִּקְדָּשׁ בָּרְגָלִים, שֶׁשָּׁם אֶבֶן קלז שְׁתִיָּה שֶׁמִּמֶּנּוּ הֻשְׁתַּת הָעוֹלָם, וְדֶרֶךְ שָׁם חוֹזֵר וְנִכְלָל זֶה הָעוֹלָם בְּשָׁרְשׁוֹ בִּבְחִינַת קֹדֶם הַבְּרִיאָה, וְעַל זֶה נֶאֱמַר: שָׂמַחְתִּי בְּאוֹמְרִים לִי בֵּית ה' נֵלֵךְ עוֹמְדוֹת הָיוּ רַגְלֵינוּ דַּיְקָא בִּשְׁעָרַיִךְ יְרוּשָׁלַיִם. וְעַל זֶה נֶאֱמַר: מַה יָּפוּ פְּעָמַיִךְ בַּנְּעָלִים. וְעִקַּר הָאֶבֶן שְׁתִיָּה וִיסוֹד הָעוֹלָם הוּא הַצַּדִּיק, בִּבְחִינַת כִּי לַה' מְצֻקֵּי אֶרֶץ וַיָּשֶׁת עֲלֵיהֶם תֵּבֵל. וְעַל יְדֵי הַהֲלִיכָה אֵלָיו עַל יְדֵי זֶה חוֹזֵר וְנִכְלָל כְּלָל הַבְּרִיאָה בִּבְחִינַת קֹדֶם הַבְּרִיאָה, וְנִתְבַּטֵּל כָּל הָרָע וְהַשֶּׁקֶר וְהַטֻּמְאָה וְהַמַּחֲלֹקֶת, שֶׁעִקַּר אֲחִיזָתָם בִּבְחִינַת אַחַר הַבְּרִיאָה, וְנִמְשָׁךְ שָׁלוֹם וְאַחְדּוּת בָּעוֹלָם, בִּבְחִינַת שַׁאֲלוּ שְׁלוֹם יְרוּשָׁלַיִם וְכוּ' לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בָּךְ וְכוּ' (הלכות רבית ה"ה יד). 
קכא. הִשְׁתַּטְּחוּת עַל קִבְרֵי הַצַּדִּיקִים הוּא דָּבָר גָּדוֹל מְאֹד וּמוֹעִיל לִתְשׁוּבָה מְאֹד מְאֹד. כִּי עַל יְדֵי זֶה חוֹזְרִין וּמַמְשִׁיכִין הֶאָרַת הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁל הַצַּדִּיק לְמַטָּה וְנִתְקַשֵּׁר בְּיוֹתֵר הַנְּשָׁמָה שֶׁלּוֹ בְּהַגּוּף שֶׁזֶּה בְּחִינַת חַיִּים וְשָׁלוֹם. וְזֶה הַשָּׁלוֹם הוּא גָּדוֹל בְּיוֹתֵר מֵהַשָּׁלוֹם וְהַהִתְקַשְּׁרוּת שֶׁהָיָה בֵּין נַפְשׁוֹ וְגוּפוֹ בַּחַיִּים חִיּוּתוֹ. כִּי עִקַּר הַשָּׁלוֹם הוּא לְחַבֵּר שְׁנֵי הֲפָכִים, וְכָל מַה שֶּׁהַשְּׁנֵי הֲפָכִים רְחוֹקִים בְּיוֹתֵר כְּמוֹ כֵן הַשָּׁלוֹם גָּדוֹל וְיָקָר יוֹתֵר כְּשֶׁחוֹזְרִים וּמִתְחַבְּרִים בְּיַחַד. וְעַל כֵּן אַחַר הַהִסְתַּלְּקוּת שֶׁאָז הַנְּשָׁמָה רְחוֹקָה מֵהַגּוּף בְּתַכְלִית הָרִחוּק, וּבִפְרָט נִשְׁמַת הַצַּדִּיק, וּבִפְרָט נִשְׁמַת הַצַּדִּיק הַגָּדוֹל בְּמַעֲלָה מְאֹד מְאֹד, שֶׁהַנְּשָׁמָה שֶׁלּוֹ מִסְתַּלֶּקֶת וְעוֹלָה לְמַעְלָה לְמַעְלָה בַּמָּקוֹם שֶׁעוֹלָה, וְהַגּוּף נִקְבַּר בְּתוֹךְ הָאָרֶץ, נִמְצָא שֶׁעַכְשָׁו הַנְּשָׁמָה רְחוֹקָה מֵהַגּוּף בְּתַכְלִית וּכְשֶׁחוֹזְרִין וּמַמְשִׁיכִין עַכְשָׁו הֶאָרַת הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁתָּאִיר בְּתוֹךְ הַגּוּף, זֶה בְּחִינַת שָׁלוֹם גָּדוֹל וְנִפְלָא בְּיוֹתֵר, שֶׁזֶּה בְּחִינַת יָבוֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם שֶׁנֶּאֱמַר עַל פְּטִירַת הַצַּדִּיקִים. כִּי בֶּאֱמֶת הַצַּדִּיק הַגָּדוֹל אַף עַל פִּי שֶׁנִּשְׁמָתוֹ מִסְתַּלֶּקֶת וְעוֹלָה לְמַעְלָה לְמַעְלָה, אַף עַל פִּי כֵן עִקַּר הַשְּׁלֵימוּת שֶׁתִּהְיֶה לְמַטָּה גַּם כֵּן כַּמְּבֹאָר בְּמָקוֹם אַחֵר. וְאָז עַל יְדֵי הַפְלָגַת עֹצֶם הַשָּׁלוֹם הַזֶּה שֶׁזּוֹכֶה עַכְשָׁו עַל יְדֵי זֶה הוּא יָכוֹל לְקַשֵּׁר וּלְהַמְשִׁיךְ כֻּלָּם לְהַשֵּׁם יִתְבָּרַךְ, אֲפִלּוּ הָרְחוֹקִים מִן הַקְּדֻשָּׁה מְאֹד מְאֹד. וְעַל כֵּן עַל יְדֵי זֶה הוּא יָכוֹל לְקַשֵּׁר וּלְהַמְשִׁיךְ כֻּלָּם לְהַשֵּׁם יִתְבָּרַךְ, אֲפִלּוּ הָרְחוֹקִים מִן הַקְּדֻשָּׁה מְאֹד מְאֹד. וְעַל כֵּן עַל יְדֵי שֶׁבָּאִין עַל קִבְרוֹ הַקָּדוֹשׁ, וְעַל יְדֵי הַבְּכִיּוֹת וְהַתְּפִלּוֹת שֶׁמִּתְפַּלְּלִין וּמִתְחַנְּנִין שָׁם, עַל יְדֵי זֶה חוֹזְרִין וּמְעוֹרְרִין בְּיוֹתֵר נִשְׁמַת הַצַּדִּיק הָאֱמֶת וּמֵאִיר בְּיוֹתֵר לְמַטָּה בְּזֶה הָעוֹלָם הַגַּשְׁמִי, כִּי צַדִּיקַיָּא שְׁכִיחֵי יַתִּיר בְּהַאי עָלְמָא בָּתַר דְּאִסְתַּלְּקוּ כְּמוֹ שֶׁכָּתוּב בַּזֹּהַר הַקָּדוֹשׁ. וְנִתְקַשֵּׁר נִשְׁמַת הַצַּדִּיק בְּיוֹתֵר בְּזֶה הָעוֹלָם וְנִתְרַבֶּה הַשָּׁלוֹם בְּיוֹתֵר, עַד שֶׁעַל יְדֵי זֶה יְכוֹלִין לְהַמְשִׁיךְ כָּל הָעוֹלָם לַעֲבוֹדָתוֹ יִתְבָּרַךְ. וּמֵחֲמַת שֶׁדֶּרֶךְ הַשָּׁלוֹם לְהִתְלַבֵּשׁ בִּמְרִירוּת כַּמְּבֹאָר בִּפְנִים, עַל כֵּן צְרִיכִין לְהִתְמַרְמֵר מְאֹד עַל פְּטִירַת הַצַּדִּיק, וְעַל מַה שֶּׁרְחוֹקִים כָּל כָּךְ עֲדַיִין מֵהַשֵּׁם יִתְבָּרַךְ, שֶׁזֶּה בְּחִינַת הַבְּכִיָּה וְהַמְּרִירוּת שֶׁבּוֹכִין בְּמַר נֶפֶשׁ עַל קִבְרֵי הַצַּדִּיקִים, כְּדֵי לְהַחֲזִיר וּלְהַמְשִׁיךְ הַשָּׁלוֹם שֶׁהוּא מִתְלַבֵּשׁ בַּמְּרִירוּת כַּנַּ"ל. וְעַל יְדֵי הַמְּרִירוּת וְהַלֵּב נִשְׁבָּר זוֹכִין אַחַר כָּךְ לְשִׂמְחָה, שֶׁהִיא בְּחִינַת שָׁלוֹם בְּחִינַת כִּי בְּשִׂמְחָה תֵּצֵאוּ וּבְשָׁלוֹם תּוּבָלוּן. וְזֶה בְּחִינַת הַמִּזְמוֹרֵי תְּהִלִּים שֶׁאוֹמְרִים שָׁם עַל קִבְרֵי הַצַּדִּיקִים שֶׁהֵם בְּחִינַת עֲשָׂרָה מִינֵי נְגִינָה שֶׁנֶּאֱמַר בָּהֶם סֵפֶר תְּהִלִּים שֶׁהֵם מְקוֹר הַשִּׂמְחָה כַּיָּדוּעַ (הלכות כתובת קעקע הלכה ג,

). 
קלז. עִקַּר מַה שֶּׁמְּקַבֵּל הַתַּלְמִיד מֵרַבּוֹ הוּא מַה שֶּׁהָיָה נִסְתָּר וְנֶעֱלָם מִמֶּנּוּ עַד עַתָּה. וְהָרַב הֵאִיר עֵינָיו עַד שֶׁנִּתְגַּלָּה לוֹ מַה שֶּׁהָיָה נִסְתָּר מִמֶּנּוּ, מֵחֲמַת שֶׁהַנִּסְתָּר הוּא בְּחִינַת נִשְׁמַע בְּחִינַת תְּפִלָּה שֶׁהִיא בְּחִינַת עֲמִידָה וְהִיא בְּחִינַת יִרְאָה כַּמְּבֹאָר בִּפְנִים. עַל כֵּן צְרִיכִין לַעֲמֹד וְלָקוּם לִפְנֵי הָרַב וְלִירָא מִמֶּנּוּ, מֵחֲמַת שֶׁהָרַב נֶגֶד הַתַּלְמִיד הוּא בְּחִינַת נִסְתָּר בְּחִינַת נִשְׁמָע בְּחִינַת עֲמִידָה בְּחִינַת יִרְאָה כַּנַּ"ל. וְגַם בִּפְנֵי שְׁאָר זְקֵנִים וַחֲכָמִים צְרִיכִין לָקוּם מִלְּפָנָיו, כִּי מֵאַחַר שֶׁהוּא זָקֵן שֶׁקָּנָה חָכְמָה שֶׁקָּנָה דַּיְקָא, כִּי זָכָה לְהַשִּׂיג מַה שֶּׁהָיָה נִסְתָּר מִמֶּנּוּ וְהָיָה בִּבְחִינַת תּוֹרַת ה', וְעַכְשָׁו כְּשֶׁמַּשִּׂיג זֶה הַדָּבָר הִיא קמה בִּבְחִינַת תּוֹרָתוֹ וְקָנָה זוֹ הַחָכְמָה וְהַהַשָּׂגָה לִהְיוֹת שֶׁלּוֹ. וְעַל כֵּן חַיָּבִים לָקוּם וְלַעֲמֹד לְפָנָיו, כִּי הַנִּסְתָּר הוּא בְּחִינַת עֲמִידָה. וְכֵן צְרִיכִין לַעֲמֹד וְלָקוּם מִפְּנֵי בַּעַל שֵׂיבָה שֶׁל שִׁבְעִים שָׁנָה, כִּי שִׁבְעִים שָׁנָה הֵם נֶגֶד בְּחִינַת שִׁבְעִים פָּנִים לַתּוֹרָה. וְעַל כֵּן מִי שֶׁזּוֹכֶה לְשֵׂיבָה וְעָבְרוּ עָלָיו כְּבָר שִׁבְעִים שָׁנָה, נִמְצָא שֶׁהוּא מְקַבֵּל עַכְשָׁו חִיּוּתוֹ מִבְּחִינַת הַדְרַת פָּנִים, מִבְּחִינַת נִסְתָּר שֶׁהוּא בִּבְחִינַת לְמַעְלָה מִכָּל הַשִּׁבְעִים פָּנִים, וְשָׁם הוּא בְּחִינַת הַדְרַת פָּנִים בְּחִינַת עֲמִידָה, עַל כֵּן צְרִיכִין לְהַדֵּר פָּנָיו וְלָקוּם לְפָנָיו (הלכות כבוד רבו הלכה ב). 
קלח. כְּלַל הַצַּדִּיקִים שֶׁבְּכָל דּוֹר הֵם בְּחִינַת שִׁבְעָה רוֹעִים, וְהֵם עוֹסְקִים לְגַדֵּל אֱמוּנַת יִשְׂרָאֵל וּלְהַשְׁלִימָהּ עַל יְדֵי הָרוּחַ נְבוּאָה שֶׁיֵּשׁ לָהֶם, וְהֵם בְּחִינַת שִׁבְעָה קְנֵי מְנוֹרָה. בְּחִינַת שֶׁבַע שְׁנֵי הַשּׂבַע כַּמְּבֹאָר בִּפְנִים. אֲבָל יֵשׁ כְּנֶגְדָּם מַנְהִיגִים וְרוֹעִים שֶׁל שֶׁקֶר בְּחִינַת נְבִיאֵי הַשֶּׁקֶר, וְהֵם מְבַלְבְּלִים אֶת הָאֱמוּנָה הַקְּדוֹשָׁה וְנִקְרָאִים שֶׁבַע שְׁנֵי הָרָעָב. וְהֵם מַסְתִּירִים וּמְכַסִּים אוֹר הַצַּדִּיקִים אֲמִתִּיִּים עַד שֶׁאֵין נִכָּרִים כְּלָל, וְאֵין רוֹאִים אוֹתָם כְּלָל כְּאִלּוּ אֵינָם בָּעוֹלָם חַס וְשָׁלוֹם, שֶׁזֶּה בְּחִינַת וַתִּבְלַעְנָה שֶׁבַע פָּרוֹת הָרָעוֹת וְכוּ' וְלֹא נוֹדַע כִּי בָּאוּ אֶל קִרְבֶּנָּה. וְאָז כְּשֶׁמִּתְגַּבְּרִין שֶׁבַע שְׁנֵי הָרָעָב שֶׁהֵם בְּחִינַת הַמַּנְהִיגִים שֶׁל שֶׁקֶר עַד שֶׁאֵין יוֹדְעִין עַל יְדֵי זֶה מֵהַצַּדִּיקִים אֲמִתִּיִּים שֶׁבְּאוֹתוֹ דּוֹר, אָז צְרִיכִין לְפַרְנֵס וּלְהַחֲיוֹת אֶת עַצְמוֹ בְּהַתּוֹרָה שֶׁגִּלּוּ לָנוּ הַצַּדִּיקִים אֲמִתִּיִּים שֶׁלְּפָנֵינוּ. וּצְרִיכִין אָנוּ לֵילֵךְ בְּדַרְכֵיהֶם עַד שֶׁיְרַחֵם עָלֵינוּ הַשֵּׁם יִתְבָּרַךְ וִיגַלֶּה לָנוּ גַּם אֶת הַצַּדִּיקֵי אֱמֶת שֶׁבַּדּוֹר הַזֶּה שֶׁיֵּשׁ לָהֶם רוּחַ נְבוּאָה רוּחַ הַקֹּדֶשׁ אֲמִתִּי, שֶׁעַל יְדֵי זֶה מְבָרְרִין הַמְדַמֶּה וּמַמְשִׁיכִין שְׁלֵימוּת הָאֱמוּנָה בְּיִשְׂרָאֵל, שֶׁזֶּה בְּחִינַת אִם לֹא תֵּדְעִי לָךְ הַיָּפָה בַּנָּשִׁים צְאִי לָךְ בְּעִקְבֵי הַצֹּאן כַּמְּבֹאָר בְּמָקוֹם אַחֵר. וְזֶה מְרֻמָּז גַּם בְּהָעֵצָה שֶׁנָּתַן יוֹסֵף הַצַּדִּיק לְבַטֵּל תֹּקֶף הָרְעָבוֹן שֶׁל שֶׁבַע שְׁנֵי הָרָעָב, עַל יְדֵי שֶׁיְּקַבְּצוּ אֶת אֹכֶל הַשָּׁנִים הַטּוֹבוֹת וְהָיוּ לְפִקָּדוֹן לָאָרֶץ וְכוּ' כַּמְּבֹאָר בִּפְנִים (שם הלכה ג

). 
קלט. כְּמוֹ שֶׁאָמְרו רַבּוֹתֵינוּ זַ"ל שֶׁנִּתְפַּזְּרוּ הַשְּׁבָטִים בְּכָל שַׁעֲרֵי מִצְרַיִם לְבַקֵּשׁ אֶת יוֹסֵף בִּמְסִירַת נֶפֶשׁ אִם לֵיהָרֵג חַס וְשָׁלוֹם וְכוּ' וְזֶה הָיָה תִּקּוּן לְמַה שֶּׁפָּגְמוּ תְּחִלָּה בִּכְבוֹד יוֹסֵף הַצַּדִּיק. עַד שֶׁעַל יְדֵי זֶה זָכוּ שֶׁנִּתְוַדַּע לָהֶם יוֹסֵף וְזָכוּ לְכָל טוּב עַל יָדוֹ בִּבְחִינַת כִּי לְמִחְיָה שְׁלָחַנִּי אֱלֹקִים לִפְנֵיכֶם וְכוּ'. כְּמוֹ כֵן צְרִיכִין בְּכָל דּוֹר וָדוֹר לְשׁוֹטֵט וּלְבַקֵּשׁ וּלְחַפֵּשׂ מְאֹד מְאֹד אֶת הַצַּדִּיק הָאֲמִתִּי בְּחִינַת יוֹסֵף בְּכָל מִינֵי חִפּוּשׂ בִּמְסִירַת נֶפֶשׁ מַמָּשׁ. כִּי עִקַּר הַחִיּוּת וְהַקִּיּוּם וְהַשְּׁאֵרִית שֶׁל כָּל יִשְׂרָאֵל וְכָל הָעוֹלָמוֹת הַתְּלוּיִים בָּהֶם הַכֹּל עַל יְדֵי הַצַּדִּיק הָאֱמֶת בְּחִינַת יוֹסֵף שֶׁזּוֹכִין יִשְׂרָאֵל לְבַקְּשׁוֹ עַד שֶׁמּוֹצְאִין אוֹתוֹ וּמִתְקָרְבִים אֵלָיו. וְעַל יְדֵי זֶה זוֹכִין לִגְאֻלָּה שְׁלֵימָה וּלְהַשִּׁיר שֶׁיִּתְעַר לֶעָתִיד. אַשְׁרֵי הַזּוֹכֶה וּמְחַכֶּה וּמִשְׁתּוֹקֵק לָזֶה בֶּאֱמֶת (שם כב). 
קמ. כָּל דִּבְרֵי הַצַּדִּיקִים וְהַחֲכָמִים אֲמִתִּיִּים הַנֶּאֱמָרִים בְּרוּחַ הַקֹּדֶשׁ בִּפְרָט בְּמַדְרֵגָה גְּבוֹהָה וְנִשְׂגָבָה הֵם סוֹבְלִין הַכֹּל כָּל דִּבְרֵי אֱמֶת שֶׁמִּתְיַגְּעִין וּמוֹצְאִין בָּהֶם כָּל אֶחָד כְּפִי דַּעְתּוֹ (הלכות מלמדים הלכה ד

). 
קנ. מַה שֶּׁעִקַּר הִתְעוֹרְרוּת לִתְשׁוּבָה נִמְשָׁךְ רַק עַל הַצַּדִּיקִים אֲמִתִּיִּים וְכֵן גֹּדֶל מַעֲלַת קְדֻשַּׁת קִבְרֵי הַצַּדִּיקִים הַקְּדוֹשִׁים - עַיֵּן אֱלוּל, רֹאשׁ הַשָּׁנָה וְכוּ' אוֹת קלה קלו. 
